package com.airesumebuilder.feature.subscription.service;import com.airesumebuilder.common.exception.ValidationException;import com.airesumebuilder.feature.subscription.repository.SubscriptionRepository;import java.time.Instant;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SubscriptionService{private final SubscriptionRepository repository;public SubscriptionService(SubscriptionRepository r){repository=r;}@Transactional public Subscription current(String email){Subscription s=repository.current(email);return s==null?repository.createFree(email):s;}@Transactional(readOnly=true)public List<Subscription>history(String email){return repository.history(email);}@Transactional public Subscription cancel(String email){Subscription current=repository.current(email);if(current==null)throw new ValidationException("No current subscription exists.");if("FREE".equals(current.plan()))throw new ValidationException("The free plan cannot be cancelled.");repository.cancelCurrent(email);return repository.createFree(email);}public record Subscription(long id,String plan,String status,boolean current,Instant startsAt,Instant endsAt){} }
